contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Try to withdraw and assert that withdraw cannot make this contract richer than before
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // ensure the test contract can receive Ether from C.transfer during withdraw
        // No precondition on amount; we allow try/catch to observe revert behavior

        // record balances observable externally
        uint256 beforeSelf = address(this).balance;
        uint256 beforeC = address(c).balance;

        bool reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterSelf = address(this).balance;
        uint256 afterC = address(c).balance;

        // General rule: withdraw cannot increase this contract's observable ether balance unless the contract's balance decreased accordingly by at least the same amount; if it reverted then nothing guaranteed about balances except no successful transfer occurred
        // Formally: either the call reverted, or (afterSelf >= beforeSelf && beforeC >= afterC && beforeC - afterC >= afterSelf - beforeSelf)
        assert(reverted || (afterSelf >= beforeSelf && beforeC >= afterC && (beforeC - afterC) >= (afterSelf - beforeSelf)));
    }

    receive() external payable {}
}

